// spec: specs/customers-pricing.md §7 · кейсы .qa/tests/customers/cust-01, cust-02, cust-03 · seed: tests/seed.admin.spec.ts
// #ea0fde (עבר QA 29.10, просьба клиента): admin «לקוח חדש» — переключатель «יצירת קישור הצטרפות» (по умолчанию вкл.).
//   Выкл. → «שמירת הלקוח», клиент в списке без ссылки; вкл. → прежний поток «יצירת לקוח וקישור הזמנה» → «החשבון נפתח».
// #5a2dbd (עבר QA 29.10): клиент без ссылки — «ללא כניסה לקטלוג» (не «ממתין להזמנה»); со ссылкой, не зарегистрирован — «ממתין להזמנה».
//   Конечный статус читается после ответа GET customer_invites (до ответа — скелет, #08cb68; см. customer-status-loading.spec.ts).
// Данные: QA-AUTO-cust-ea0fde-<ts>-*; без заказов; ссылку не копируем/не отправляем; afterAll — удаление через admin.
import { test, expect } from '@playwright/test';
import {
  authFile, rowOf, openList, openListReady, search, openNewCustomer, deleteCustomersByPrefix,
  SUBTITLE_NO_LINK, SUBTITLE_LINK, BTN_SAVE, BTN_LINK, SWITCH_LINK, ST_NO_CATALOG, ST_PENDING, ST_ACTIVE, TEST_PHONE,
} from './_customers';

test.use({ storageState: authFile('admin') });
test.describe.configure({ mode: 'serial' });

const PREFIX = `QA-AUTO-cust-ea0fde-${Date.now().toString().slice(-7)}`;
const NOLINK = `${PREFIX}-nolink`;
const LINK = `${PREFIX}-link`;

test.describe('customers — לקוח חדש בלי קישור הצטרפות (#ea0fde)', () => {
  test.afterAll(async ({ browser }) => {
    await deleteCustomersByPrefix(browser, test.info().project.use.baseURL, PREFIX);
  });

  test('מתג «יצירת קישור הצטרפות» דלוק כברירת מחדל; כבוי → כותרת «הלקוח יישמר…» ו«שמירת הלקוח»; ולידציה בשני המצבים #ea0fde @desktop @data', async ({ page }) => {
    await openList(page);
    const dlg = await openNewCustomer(page);
    const sw = dlg.getByRole('switch', { name: SWITCH_LINK });
    const name = dlg.getByRole('textbox', { name: /^שם העסק/ });
    const phone = dlg.getByRole('textbox', { name: 'טלפון' });
    const email = dlg.getByRole('textbox', { name: 'אימייל' });

    // по умолчанию — вкл., прежний поток со ссылкой
    await expect(sw).toHaveAttribute('aria-checked', 'true');
    await expect(dlg.getByText(SUBTITLE_LINK)).toBeVisible();
    await expect(dlg.getByRole('button', { name: BTN_LINK })).toBeVisible();

    // вкл.: валидация
    await dlg.getByRole('button', { name: BTN_LINK }).click();
    await expect(dlg.getByText('נא להזין שם עסק')).toBeVisible();
    await name.fill(`${PREFIX}-invalid`);
    await phone.fill('12');
    await email.fill('bad@');
    await dlg.getByRole('button', { name: BTN_LINK }).click();
    await expect(dlg.getByText(/מספר טלפון קצר מדי/)).toBeVisible();
    await expect(dlg.getByText('כתובת אימייל לא תקינה')).toBeVisible();

    // выкл.
    await sw.click();
    await expect(sw).toHaveAttribute('aria-checked', 'false');
    await expect(dlg.getByText(SUBTITLE_NO_LINK)).toBeVisible();
    await expect(dlg.getByRole('button', { name: BTN_SAVE })).toBeVisible();
    await expect(dlg.getByRole('button', { name: BTN_LINK })).toHaveCount(0);

    // выкл.: те же правила валидации
    await name.fill('');
    await dlg.getByRole('button', { name: BTN_SAVE }).click();
    await expect(dlg.getByText('נא להזין שם עסק')).toBeVisible();
    await name.fill(`${PREFIX}-invalid`);
    await dlg.getByRole('button', { name: BTN_SAVE }).click();
    await expect(dlg.getByText(/מספר טלפון קצר מדי/)).toBeVisible();
    await expect(dlg.getByText('כתובת אימייל לא תקינה')).toBeVisible();
    await expect(dlg.getByRole('heading', { name: 'לקוח חדש' })).toBeVisible();

    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    await search(page, `${PREFIX}-invalid`);
    await expect(rowOf(page, `${PREFIX}-invalid`)).toHaveCount(0);
  });

  test('מתג כבוי → «שמירת הלקוח»: POST customers 201, בלי חלון «החשבון נפתח», הלקוח ברשימה בסטטוס «ללא כניסה לקטלוג»; ב-⋮ יש «קישור הצטרפות», ל«test» (פעיל) — אין #ea0fde #5a2dbd @desktop @data', async ({ page }) => {
    await openList(page);
    const dlg = await openNewCustomer(page);
    await dlg.getByRole('switch', { name: SWITCH_LINK }).click();
    await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(NOLINK);
    await dlg.getByRole('textbox', { name: 'איש קשר' }).fill('QA בדיקה');
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('0501234567');
    const [resp] = await Promise.all([
      page.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
      dlg.getByRole('button', { name: BTN_SAVE }).click(),
    ]);
    expect(resp.status(), 'POST customers').toBe(201);
    await expect(page.getByRole('dialog')).toHaveCount(0, { timeout: 15_000 });
    await expect(page.getByRole('heading', { name: 'החשבון נפתח' })).toHaveCount(0);

    await openListReady(page);
    await search(page, NOLINK);
    const row = rowOf(page, NOLINK);
    await expect(row).toBeVisible({ timeout: 20_000 });
    await expect(row).toContainText('0501234567');
    // #5a2dbd «מה רצוי»: клиент без ссылки — не «ממתין להזמנה»; программист: «ללא כניסה לקטלוג»
    await expect(row).toContainText(ST_NO_CATALOG);
    await expect(row).not.toContainText(ST_PENDING);
    await row.getByRole('button', { name: 'פעולות' }).click();
    // ссылку можно выдать позже из меню клиента; сам пункт не нажимаем
    await expect(page.getByRole('menuitem', { name: 'קישור הצטרפות' })).toBeVisible();
    await page.keyboard.press('Escape');

    // в базе несколько «test» — берём закреплённого за testtest по телефону
    await search(page, 'test');
    const active = rowOf(page, TEST_PHONE);
    await expect(active).toContainText(ST_ACTIVE);
    await active.getByRole('button', { name: 'פעולות' }).click();
    await expect(page.getByRole('menuitem', { name: 'כרטיס לקוח' })).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'קישור הצטרפות' })).toHaveCount(0);
    await page.keyboard.press('Escape');
  });

  test('מתג דלוק (ברירת מחדל) → «יצירת לקוח וקישור הזמנה» → חלון «החשבון נפתח» → «סגירה», הלקוח ברשימה בסטטוס «ממתין להזמנה» #ea0fde #6a38cf5d #5a2dbd @desktop @data', async ({ page }) => {
    await openList(page);
    const dlg = await openNewCustomer(page);
    await expect(dlg.getByRole('switch', { name: SWITCH_LINK })).toHaveAttribute('aria-checked', 'true');
    await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(LINK);
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('0501234568');
    await dlg.getByRole('button', { name: BTN_LINK }).click();
    await expect(dlg.getByRole('heading', { name: 'החשבון נפתח' })).toBeVisible({ timeout: 15_000 });
    // ссылку не копируем и не отправляем — только закрываем
    await dlg.getByRole('button', { name: 'סגירה' }).click();
    await openListReady(page);
    await search(page, LINK);
    await expect(rowOf(page, LINK)).toContainText('0501234568', { timeout: 20_000 });
    // #5a2dbd «מה רצוי»: «ממתין להזמנה נשאר ללקוח שנוצר עם קישור ועדיין לא נרשם»
    await expect(rowOf(page, LINK)).toContainText(ST_PENDING);
  });
});
